        'sections' => [
            [
                'heading_bn' => '১. ব্যবসার ফলাফলের সঙ্গে campaign goal মেলান',
                'heading_en' => '1. Match the campaign goal to the business outcome',
                'body_bn' => 'আপনি sale, lead, নাকি website visit চান—প্রথমে ঠিক করুন। Google Ads-এ campaign objective ও type সেই লক্ষ্য এবং বিজ্ঞাপন কোথায় দেখা যাবে তার সঙ্গে সম্পর্কিত। শুধু traffic বাড়ানো যদি বিক্রির লক্ষ্য পূরণ না করে, তবে traffic-কে success ধরে নেবেন না।',
                'body_en' => 'Decide whether you want sales, leads, or website visits. Google Ads campaign objectives and types guide settings and where ads can appear. If traffic is not the goal, do not treat clicks alone as success.',
            ],
            [
                'heading_bn' => '২. কাস্টমারের search phrase থেকে keyword নিন',
                'heading_en' => '2. Build keywords from customer searches',
                'body_bn' => 'আপনার অফার, সার্ভিস ও এলাকার সঙ্গে সরাসরি সম্পর্কিত শব্দ বেছে নিন। শুরুতে keyword-এর match type বুঝে নিন, Search terms report দেখুন, এবং অপ্রাসঙ্গিক query কমাতে negative keyword ব্যবহার করুন।',
                'body_en' => 'Choose terms directly related to your offer, service, and location. Understand keyword match types, review the Search terms report, and use negative keywords to reduce irrelevant queries.',
            ],
            [
                'heading_bn' => '৩. বিজ্ঞাপন ও landing page-এ একই কথা বলুন',
                'heading_en' => '3. Align the ad and landing page',
                'body_bn' => 'বিজ্ঞাপনের মূল offer, সার্ভিস ও CTA landing page-এ স্পষ্টভাবে দেখান। পেজটি মোবাইলে ব্যবহারযোগ্য, দ্রুত এবং প্রাসঙ্গিক হওয়া উচিত। click-এর পর মানুষ কী করবে তা যেন বুঝতে পারে।',
                'body_en' => 'Make the offer, service, and call to action in the ad clear on the landing page too. Keep it relevant, mobile-friendly, and fast, with an obvious next step.',
            ],
            [
                'heading_bn' => '৪. বাজেট এমনভাবে ঠিক করুন যেন পরীক্ষা করা যায়',
                'heading_en' => '4. Set a budget you can test with',
                'body_bn' => 'দৈনিক বাজেট এবং সর্বোচ্চ গ্রহণযোগ্য খরচ আগে নির্ধারণ করুন। অল্প সময়ে অনেক campaign, ad group, keyword ও creative খুলে budget ছড়িয়ে দেবেন না। পরিবর্তন করলে কী বদলালেন তা নোট করুন।',
                'body_en' => 'Set a daily budget and an acceptable cost limit before launch. Avoid spreading a small budget across too many campaigns, ad groups, and keywords. Record what you change so you can interpret results.',
            ],
            [
                'heading_bn' => '৫. Conversion tracking যাচাই করুন',
                'heading_en' => '5. Verify conversion tracking',
                'body_bn' => 'ফর্ম জমা, purchase বা নির্দিষ্ট lead action সঠিকভাবে record হচ্ছে কি না পরীক্ষা করুন। Tracking ভুল হলে automated bidding ও রিপোর্ট ভুল signal পেতে পারে। Privacy notice ও প্রয়োজনীয় consent-ও মানুন।',
                'body_en' => 'Check that form submissions, purchases, or qualified lead actions are recorded correctly. Incorrect tracking can make reporting and automated bidding rely on poor signals. Respect privacy notices and required consent.',
            ],
            [
                'heading_bn' => '৬. ফল দেখে নিয়মিত অপটিমাইজ করুন',
                'heading_en' => '6. Optimise based on results',
                'body_bn' => 'Clicks-এর পাশাপাশি conversion, qualified lead, cost per result এবং বিক্রির গুণমান দেখুন। Search terms review করুন, অপ্রাসঙ্গিক keyword বাদ দিন, ভালো performing message পরীক্ষা করুন, এবং পরিবর্তনের পরে পর্যাপ্ত ডেটা আসতে দিন।',
                'body_en' => 'Review conversions, qualified leads, cost per result, and sales quality—not just clicks. Check search terms, remove irrelevant queries, test useful ad messages, and allow enough data after changes.',
            ],
        ],
